select id, card_id, transaction_date, transaction_desc, balance_currency, balance_money, card_type_id, card_type_name, demoarea from salary where 1 = 1
and transaction_date >= #{salary.transactionDateStart,jdbcType=DATE}
and transaction_date <= #{salary.transactionDateEnd,jdbcType=DATE}
and card_type_name = #{salary.cardTypeName,jdbcType=VARCHAR}
and ( demoarea like CONCAT('%', #{salary.demoArea,jdbcType=VARCHAR}, '%') or transaction_desc like CONCAT('%', #{salary.demoArea,jdbcType=VARCHAR}, '%') )
and YEAR(transaction_date) = #{salary.year,jdbcType=VARCHAR}
order by transaction_date desc limit #{page.pageSize,jdbcType=INTEGER} offset #{page.recordBegin,jdbcType=INTEGER}

    	select count(id) from salary
        where 1 = 1


				and transaction_date >= #{salary.transactionDateStart,jdbcType=DATE} 


				and transaction_date <= #{salary.transactionDateEnd,jdbcType=DATE}


				and card_type_name = #{salary.cardTypeName,jdbcType=VARCHAR}


             	and (
                    demoarea like CONCAT('%', #{salary.demoArea,jdbcType=VARCHAR}, '%')
                    or transaction_desc like CONCAT('%', #{salary.demoArea,jdbcType=VARCHAR}, '%')
                )


            	and YEAR(transaction_date) = #{salary.year,jdbcType=VARCHAR}
